-- Terra — demo seed. Generated by tools/build_seed.mjs; do not edit by hand.
--
-- Run this in the Supabase SQL Editor (Dashboard → SQL Editor → New query →
-- paste → Run), the same way the schema migration was applied. The editor
-- runs as a privileged role, which is what makes it able to write `needs`:
-- that table deliberately has no insert policy, so neither the anon key nor
-- a signed-in user can add rows. Only the service role and the SQL editor.
--
-- Safe to re-run. Everything below is owned by one fixed demo user, and the
-- script clears that user's rows before inserting, so you get the same 32
-- ministries and 65 needs every time rather than a second copy of them.
--
-- ALL OF THIS DATA IS FICTIONAL. Every organisation, person and need is
-- invented, and every contact address is on example.org, which cannot
-- receive mail. To remove it again:
--
--   delete from auth.users where id = '00000000-0000-4000-8000-00000000d3m0';
--
-- which cascades to the profile, the ministries and their needs.

begin;

-- ---------------------------------------------------------- demo owner
--
-- ministries.owner_id is not null and references profiles(id), which
-- references auth.users(id) — so the seed needs a user to hang off. It has
-- no password at all: the column is nullable (OAuth users carry none), and a
-- null there means no credential can ever match, which is what you want of
-- an account that exists only to own rows. Writing a hash instead would have
-- pulled in pgcrypto's crypt() for no benefit. The on_auth_user_created
-- trigger writes the matching profile.
insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  created_at, updated_at, raw_app_meta_data, raw_user_meta_data,
  confirmation_token, recovery_token, email_change_token_new, email_change
)
values (
  '00000000-0000-0000-0000-000000000000', '00000000-0000-4000-8000-00000000d3m0', 'authenticated', 'authenticated',
  'demo@example.org', null, now(),
  now(), now(), '{"provider":"email","providers":["email"]}'::jsonb,
  '{"full_name":"Terra demo data","role":"ministry"}'::jsonb,
  '', '', '', ''
)
on conflict (id) do nothing;

-- The trigger covers a fresh insert; this covers a database where the user
-- already exists but the profile was removed.
insert into public.profiles (id, full_name, role)
values ('00000000-0000-4000-8000-00000000d3m0', 'Terra demo data', 'ministry')
on conflict (id) do update set role = 'ministry';

-- Clear this owner's previous seed. Needs cascade from ministries.
delete from public.ministries where owner_id = '00000000-0000-4000-8000-00000000d3m0';

