-- --------------------------------------------------------------- needs
--
-- status 'live' explicitly: the column defaults to pending_review so that
-- anything reaching the table without passing moderation stays invisible,
-- and only live rows are readable by the public policy. Seed data has no
-- moderation pass to go through, so it is marked live here.
--
-- Joined on slug rather than carrying ministry uuids, so the ids stay
-- whatever Postgres generated and this file has no machine state in it.
insert into public.needs
  (ministry_id, title, type, urgency, people, focus, remote, commitment, skills, detail, posted, status)
select m.id, 'Ger insulation kits', 'supplies', 'urgent', 0, 'shelter', false, '40 kits before November', array['Logistics']::text[], 'Felt and canvas outer layers for forty gers on the northern slopes. Nights are already below freezing and the coal ration does not stretch to an uninsulated tent.', '2026-08-29'::date, 'live' from public.ministries m where m.slug = 'ulaanbaatar-ger'
union all
